public class PrimeCounter {

    public static int countPrimes(int n) {
        int count = 0;
        for (int candidate = 2; candidate < n; candidate++) {
            boolean isPrime = true;
            for (int d = 2; d * d <= candidate; d++) {
                if (candidate % d == 0) {
                    isPrime = false;
                    break;
                }
            }
            if (isPrime) {
                count++;
            }
        }
        return count;
    }
}
